},
|attr| {
    let attr = if let AttributeType::Type(_) = &reference.attribute_data.kind {
        // If we're evaluating a container query, we haven't run the cascade
        // and populated substitution_functions.attributes, so we can't do the
        // get_attr() lookup here.
        // TODO: This means chained attr() references will not work reliably in
        // container style queries:
        // https://bugzilla.mozilla.org/show_bug.cgi?id=2028861
        if computed_context.in_container_query {
            attr
        } else {
            substitution_functions
                .get_attr(&reference.name, namespace?)
                .map(|v| v.to_variable_value())?
                .css
        }
    } else {
        attr
    };
    let mut parser = Parser::new(&attr);
    match &reference.attribute_data.kind {
        AttributeType::Unit(unit) => {
            let css = {
                let mut s = String::from(parse_attr_number(&mut parser).ok()?);
                s.push_str(unit.as_ref());
                s
            };
            let serialization = match unit {
                AttrUnit::Number => TokenSerializationType::Number,
                AttrUnit::Percentage => TokenSerializationType::Percentage,
                _ => TokenSerializationType::Dimension,
            };
            let value =
                ComputedValue::new(css, url_data, serialization, serialization);
            Some(Substitution::from_value(
                value, /* attr_tainted */ true,
            ))
        },
        AttributeType::Type(_) => {
            let value = reference
                .attribute_data
                .parse_typed_value(&mut parser, url_data, property_id)
                .ok()?;
            let value = value.to_variable_value();
            Some(Substitution::from_value(
                value, /* attr_tainted */ true,
            ))
        },
        AttributeType::RawString | AttributeType::None => {

    let substitution = substitution.filter(|value| {
        !(reference.substitution_kind == SubstitutionFunctionKind::Var
            && value.animation_tainted
            && !suppress_animation_taint_sink
            && matches!(property_id, Some(PropertyIdRef::NonCustom(id)) if !id.is_animatable()))
    });
    if let Some(s) = substitution {
        return Ok(s);
    }

    let Some(ref fallback) = reference.fallback else {
        return Err(());
    };

    do_substitute_chunk(
        css,
        fallback.start.get(),
        reference.end - 1, // Skip the closing parenthesis of the reference value.
        fallback.first_token_type,
        fallback.last_token_type,
        url_data,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        &fallback.references.refs,
        attribute_tracker,
        seen,
        /* attr_taint */ None,
        suppress_animation_taint_sink,
    )
}

let next_var = if next.substitution_kind == SubstitutionFunctionKind::Attr {
    if !next.is_attr_with_type() {
        if let Some(ref fallback) = next.fallback
            && !next
                .attribute_data
                .non_type_primary_is_valid(&next.name, attribute_tracker)
        {
            refs_stack.push(&fallback.references);
        }
        continue;
    }
    let Some(namespace) = next.attribute_data.namespace() else {
        if let Some(ref fallback) = next.fallback {
            refs_stack.push(&fallback.references);
        }
        continue;
    };
    if !context.map().contains_attr(&next.name, namespace)
        && let Ok(val) = get_attr_value_for_cycle_resolution(
            &next.name,
            &next.attribute_data,
            url_data,
            attribute_tracker,
        )
    {
        context.map_mut().insert_attr(&next.name, namespace, val);
    }
    VarType::Attr(next.name.clone(), namespace.clone())
} else {
    VarType::Custom(next.name.clone())

debug_assert!(
    matches!(var, VarType::Custom(_) | VarType::Attr(..)),
    "Non-custom property has references?"
);

let property_id = match &var {
    VarType::Custom(name) | VarType::Attr(name, _) => Some(PropertyIdRef::from(name)),
    VarType::NonCustom(_) => unreachable!(),
};
// Visit the references in this value...
visit_value_references(
    &v.references,
    &v.url_data,
    property_id,
    index,
    references_from_non_custom_properties,
    context,
    &mut lowlink,
    &mut self_ref,
    attribute_tracker,
    &mut value_non_custom_refs,
);

// ... Then the non-custom properties this value depends on (font-size, line-height,
// color-scheme), as computed by `find_non_custom_references` above.

if in_loop {
    return None;
}

// Not in a loop, apply the value.
match var {
    VarType::Custom(ref name) | VarType::Attr(ref name, _) => {
        if let Some(ref v) = value {
            // We know we're not in a loop now, perform substitution.
            // TODO(emilio): Merge with the cycle detection loop instead?
            substitute_references_if_needed_and_apply(
                name,
                var.namespace(),
                v,
                context.stylist,
                context.computed_context,
                attribute_tracker,
            );
        }
    },
    VarType::NonCustom(non_custom) => {
        context.apply_prioritary_property(non_custom.to_prioritary_id(), attribute_tracker);
    },

/// Traverse the references in `root` (the value of a custom property or of a non-custom
/// property feeding a `NonCustom` node), creating graph edges to the referenced substitution
/// functions and updating `lowlink`/`self_ref` accordingly.
///
/// We follow var()/attr()/env() fallbacks only when the primary substitution function is
/// guaranteed-invalid (i.e. when the fallback is actually used). This matches the substitution
/// order and the resolution of https://github.com/w3c/csswg-drafts/issues/11500: cycles (or
/// dependencies) that only exist through an unused fallback don't count.
///

    // Now that the primary reference has been resolved, classify it to
    // decide whether its fallback is used.
    let kind = next.substitution_kind;
    let resolved = match kind {
        SubstitutionFunctionKind::Var => {
            let registration =
                context.stylist.get_custom_property_registration(&next.name);
            context.map().get_var(registration, &next.name)
        },
        SubstitutionFunctionKind::Attr => next
            .attribute_data
            .namespace()
            .and_then(|namespace| context.map().get_attr(&next.name, namespace)),
        SubstitutionFunctionKind::Env => unreachable!("Handled above"),
    };
    // The primary is guaranteed-invalid if it's absent from the map, or still
    // present but unresolved (i.e. part of a cycle currently being resolved).
    let mut primary_valid = false;
    if let Some(resolved) = resolved {
        if let Some(v) = resolved.as_universal() {
            primary_valid = !v.has_references();
            *non_custom_references |= v.references.flags;
        } else {
            // Resolved and computed value, no other custom references left.
            primary_valid = true;
        }
        if primary_valid && next.is_attr_with_type() {
            let value = resolved.to_variable_value();
            primary_valid = next
                .attribute_data
                .parse_typed_value(
                    &mut cssparser::Parser::new(&value.css),
                    url_data,
                    property_id,
                )
                .is_ok();
        }
    }

    if !primary_valid && let Some(ref fallback) = next.fallback {
        refs_stack.push(&fallback.references);
    }
}
